<script setup lang="ts">
import { X, ListPlus, Play } from "lucide-vue-next";
import { usePlayerStore } from "../stores/player";
import QueueRow from "./QueueRow.vue";
const player = usePlayerStore();
const emit = defineEmits<{ close: [] }>();
function onKeydown(e: KeyboardEvent) { if (e.key === "Escape") emit("close"); }
function drag(from: number, to: number) { player.moveInQueue(from, to); }
</script>
<template><aside class="queue-panel" tabindex="-1" @keydown="onKeydown"><header><h2><ListPlus :size="20"/> Queue</h2><button v-if="player.userQueue.length" class="clear" @click="player.clearQueue">Clear</button><button class="close" aria-label="Close queue" @click="emit('close')"><X :size="18"/></button></header><section v-if="player.current"><h3>Now playing</h3><div class="now"><Play v-if="player.isPlaying" :size="14" fill="currentColor"/><span>{{ player.current.title }}</span></div></section><section v-if="player.userQueue.length"><h3>Next in queue <small>{{ player.userQueue.length }}</small></h3><QueueRow v-for="(id,i) in player.userQueue" :key="`${id}-${i}`" :track="player.trackById(id)" :index="i" @play="player.playQueued(i)" @remove="player.removeFromQueue(i)" @move="drag"/></section><section v-if="player.upNextContext.length"><h3>Next from {{ player.contextName }}</h3><QueueRow v-for="track in player.upNextContext.slice(0,100)" :key="track.path" :track="track" @play="player.playContextTrack(track.path)"/></section><div v-if="!player.userQueue.length && !player.upNextContext.length" class="empty">Antrean kosong. Tambahkan lagu dengan tombol antrean pada baris lagu.</div></aside></template>
<style scoped>.queue-panel{grid-column:3;grid-row:1;min-height:0;overflow:auto;padding:20px;background:var(--surface-bg);border-radius:24px;box-shadow:var(--shadow-raised);outline:0}.queue-panel header{display:flex;align-items:center;gap:8px}.queue-panel h2{display:flex;align-items:center;gap:8px;flex:1;margin:0;font-size:18px}.close,.clear{border:0;background:transparent;color:var(--text-secondary);cursor:pointer;padding:7px;border-radius:10px}.clear{color:var(--accent)}.close:hover,.clear:hover{box-shadow:var(--shadow-raised-sm)}h3{margin:20px 0 8px;font-size:11px;color:var(--text-secondary);text-transform:uppercase;letter-spacing:.08em}h3 small{margin-left:4px}.now{display:flex;gap:8px;padding:12px;border-radius:12px;color:var(--accent);box-shadow:var(--shadow-inset)}.empty{text-align:center;color:var(--text-secondary);font-size:12px;padding:60px 12px}@media(max-width:1100px){.queue-panel{position:fixed;z-index:50;right:20px;top:20px;bottom:120px;width:340px}}
</style>
